-- =====================================================================
-- 개발·시연용 더미 시세 (한국금거래소 공개 시세 기반, 1년치)
--
-- ⚠️ 이것은 <b>우리가 고시한 값이 아니다.</b> 경쟁사가 공개한 시세를 그대로 옮긴
--    것이고, 화면에는 한성금거래소의 고시가로 표시된다. 실거래를 시작하기 전에
--    반드시 걷어내야 한다 (clear-dummy-prices.sql).
--
-- 안전장치
--   1. 주문이 한 건이라도 있으면 실행하지 않는다 — 그 주문이 참조하는 시세를
--      건드릴 수 있다
--   2. 더미가 아닌 시세가 있으면 실행하지 않는다 — 사람이 고시한 값을 덮지 않는다
--
-- 실행: psql ... -v ON_ERROR_STOP=1 -f seed-prices.sql
-- =====================================================================

BEGIN;

DO $guard$
DECLARE
    order_rows bigint;
    real_rows  bigint;
BEGIN
    SELECT count(*) INTO order_rows FROM orders;
    IF order_rows > 0 THEN
        RAISE EXCEPTION
            '주문이 % 건 있습니다. 실제 거래가 참조하는 시세를 더미로 덮을 수 없습니다.', order_rows;
    END IF;

    SELECT count(*) INTO real_rows
      FROM market_prices_effective WHERE created_by <> 'dummy-seed';
    IF real_rows > 0 THEN
        RAISE EXCEPTION
            '사람이 고시한 시세가 % 건 있습니다. 먼저 확인하세요.', real_rows;
    END IF;
END $guard$;

-- 이전 더미를 걷어낸다. append-only 트리거를 잠깐 내린다 —
-- 운영에서 하지 않는 일이지만, 더미를 갈아 끼우는 경로에서만 연다.
ALTER TABLE market_prices_effective DISABLE TRIGGER trg_mpe_guard;
DELETE FROM market_prices_effective WHERE created_by = 'dummy-seed';
ALTER TABLE market_prices_effective ENABLE TRIGGER trg_mpe_guard;

-- 원본은 (시각, 금속, 방향, 원/g) 네 값뿐이다.
-- effective_to 는 <b>다음 고시의 시각</b>이므로 LEAD() 로 만든다 — 손으로 이어 붙이면
-- 한 줄만 어긋나도 ux_mpe_current 가 막거나, 더 나쁘게는 구멍이 뚫린 채로 들어간다.
INSERT INTO market_prices_effective (
    metal_type, price_side, price_per_gram, policy_mode, policy_snapshot,
    effective_from, effective_to, change_reason, created_by, source_code, quote_at, created_at)
SELECT
    metal, side, per_gram, 'MANUAL',
    '{"mode":"MANUAL","note":"dummy seed from koreagoldx public quote","unit":"KRW/g"}'::jsonb,
    at, LEAD(at) OVER (PARTITION BY metal, side ORDER BY at),
    '개발용 더미 데이터', 'dummy-seed', 'MANUAL', at, at
-- VALUES 의 문자열은 timestamptz 로 추론되지 않는다. 여기서 한 번 캐스팅해 두면
-- LEAD() 와 아래 컬럼들이 모두 같은 타입을 쓴다.
FROM (SELECT at::timestamptz AS at, metal, side, per_gram::numeric(15,2) AS per_gram
      FROM (VALUES
